h,w=30,8
markers={(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)}
grid=[[8]*w for _ in range(h)]
for r,c in markers:grid[r][c]=7
# Fill cells strictly between marker pairs in each row/column.
for r in range(h):
    cs=sorted(c for rr,c in markers if rr==r)
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):grid[r][c]=3
for c in range(w):
    rs=sorted(r for r,cc in markers if cc==c)
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):grid[r][c]=3
print('{"action":"submit","grid":'+__import__('json').dumps(grid,separators=(',',':'))+'}')
